        assert result.tags == [Tag("work")]

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_raises(self, repo, sample_task):
        repo.add(sample_task)
        with pytest.raises(ValueError, match="already exists"):
            repo.add(sample_task)

    def test_list_empty(self, repo):
        assert list(repo.list()) == []

    def test_list_returns_all(self, repo, sample_task):
        repo.add(sample_task)
        t2 = Task(id=2, title="Second", created_at=datetime(2025, 1, 2, tzinfo=timezone.utc))
        repo.add(t2)
